        @Override public int[] globalParameters(){return globalParameters.clone();}@Override public double[] localEstimates(){return localEstimates.clone();}@Override public double[][] impliedCovariance(){return Matrices.copy(impliedCovariance);}@Override public double[] impliedMeans(){return impliedMeans.clone();}@Override public double[][] directed(){return Matrices.copy(directed);}@Override public double[][] disturbance(){return Matrices.copy(disturbance);}@Override public double[][] fullCovariance(){return Matrices.copy(fullCovariance);}@Override public double[] fullMeans(){return fullMeans.clone();}@Override public double[][] standardizedDirected(){return Matrices.copy(standardizedDirected);}
