        MutableParameter(String name,boolean shared){this.name=name;this.shared=shared;}
        void add(SemModel.Parameter parameter,Binding binding){bindings.add(binding);start+=(parameter.start()-start)/++count;scale=Math.max(scale,parameter.scale());if(parameter.lower()!=null)lower=Math.max(lower,parameter.lower());if(parameter.upper()!=null)upper=Math.min(upper,parameter.upper());}
