            for(int b=0;b<group.input().model().parameters().size();b++)if(!matched.contains(b)){var parameter=group.input().model().parameters().get(b);var signature=signature(group.input().model(),parameter);Expression expression=fixed(reference.input().model(),signature);if(expression!=null)result.add(contrast(fit,referenceName,group.input().name(),parameter.name(),signature,expression,new Expression(group.globalParameters[b],0),covariance,critical));}
